def _agent_debug_log(location: str, message: str, *, data: dict | None = None, hypothesis_id: str = ""):
    try:
        log_path = Path(__file__).resolve().parent / "debug-a5ff14.log"
        payload = {
            "sessionId": "a5ff14",
            "location": location,
            "message": message,
            "data": data or {},
            "timestamp": int(time.time() * 1000),
            "hypothesisId": hypothesis_id,
        }
        with log_path.open("a", encoding="utf-8") as handle:
            handle.write(json.dumps(payload, ensure_ascii=False) + "\n")
    except Exception:
        pass


