def _show_startup_error(message: str):
    try:
        ctypes.windll.user32.MessageBoxW(None, message, "Quest ODM Architect", 0x10)
    except Exception:
        pass

try:
    ensure_runtime_prerequisites(verbose=os.environ.get("ODM_BOOTSTRAP_VERBOSE", "1") != "0")
except Exception as exc:
    message = f"Startup prerequisite check failed.\n\n{exc}"
    print(f"[bootstrap] {message}", file=sys.stderr, flush=True)
    if getattr(sys, "frozen", False):
        _show_startup_error(message)
    raise SystemExit(1) from exc

