def _worker_root_for_session(session_id: str | None) -> Path:
    safe_session_id = re.sub(r"[^A-Za-z0-9_.-]+", "_", str(session_id or "ps_worker").strip()) or "ps_worker"
    return _runtime_support_dir() / "workers" / f"{safe_session_id}-{APP_INSTANCE_ID}"


def _version_file_path() -> Path:
    return _app_base_dir() / "VERSION"


def _load_app_version() -> str:
    candidates = [_version_file_path(), Path(__file__).resolve().parent / "VERSION"]
    for candidate in candidates:
        try:
            text = candidate.read_text(encoding="utf-8-sig").strip().lstrip("\ufeff")
        except OSError:
            continue
        if text:
            return text
    return "0.0.0"


APP_VERSION = _load_app_version()
WINDOWS_CREATE_NEW_CONSOLE = getattr(subprocess, "CREATE_NEW_CONSOLE", 0)
WINDOWS_SW_HIDE = 0


def _normalise_version_text(value: str | None) -> str:
    text = str(value or "").replace("\ufeff", "").strip()
    if text.lower().startswith("v"):
        text = text[1:]
    return text


def _version_key(value: str | None) -> tuple[int, ...]:
    parts = [int(part) for part in re.findall(r"\d+", _normalise_version_text(value))]
    return tuple(parts or [0])


def _is_version_newer(candidate: str | None, current: str | None) -> bool:
    left = list(_version_key(candidate))
    right = list(_version_key(current))
    width = max(len(left), len(right))
    left.extend([0] * (width - len(left)))
    right.extend([0] * (width - len(right)))
    return tuple(left) > tuple(right)


def _hide_process_console(pid: int | None):
    safe_pid = int(pid or 0)
    if safe_pid <= 0 or os.name != "nt":
        return
    try:
        user32 = ctypes.windll.user32
        handles = []

        @ctypes.WINFUNCTYPE(ctypes.c_bool, ctypes.c_void_p, ctypes.c_void_p)
        def enum_windows(hwnd, _lparam):
            process_id = ctypes.c_ulong()
            user32.GetWindowThreadProcessId(hwnd, ctypes.byref(process_id))
            if process_id.value == safe_pid and user32.IsWindowVisible(hwnd):
                handles.append(hwnd)
            return True

        user32.EnumWindows(enum_windows, 0)
        for handle in handles:
            user32.ShowWindow(handle, WINDOWS_SW_HIDE)
    except Exception:
        pass


def _show_process_console(pid: int | None):
    safe_pid = int(pid or 0)
    if safe_pid <= 0 or os.name != "nt":
        return
    try:
        user32 = ctypes.windll.user32
        handles = []

        @ctypes.WINFUNCTYPE(ctypes.c_bool, ctypes.c_void_p, ctypes.c_void_p)
        def enum_windows(hwnd, _lparam):
            process_id = ctypes.c_ulong()
            user32.GetWindowThreadProcessId(hwnd, ctypes.byref(process_id))
            if process_id.value == safe_pid and user32.IsWindowVisible(hwnd):
                handles.append(hwnd)
            return True

        user32.EnumWindows(enum_windows, 0)
        for handle in handles:
            user32.ShowWindow(handle, 9)
            try:
                user32.BringWindowToTop(handle)
            except Exception:
                pass
            try:
                user32.SetForegroundWindow(handle)
            except Exception:
                pass
    except Exception:
        pass


def _show_interactive_auth_window() -> bool:
    if os.name != "nt":
        return False
    try:
        user32 = ctypes.windll.user32
        handles = []
        title_tokens = (
            "sign in to your account",
            "pick an account",
            "enter password",
            "work or school account",
            "stay signed in",
            "more information required",
            "approve sign in request",
        )

        @ctypes.WINFUNCTYPE(ctypes.c_bool, ctypes.c_void_p, ctypes.c_void_p)
        def enum_windows(hwnd, _lparam):
            if not user32.IsWindowVisible(hwnd):
                return True
            length = user32.GetWindowTextLengthW(hwnd)
            if length <= 0:
                return True
            buffer = ctypes.create_unicode_buffer(length + 1)
            user32.GetWindowTextW(hwnd, buffer, len(buffer))
            title = str(buffer.value or "").strip()
            if not title:
                return True
            normalised = title.lower()
            if any(token in normalised for token in title_tokens):
                handles.append(hwnd)
            return True

        user32.EnumWindows(enum_windows, 0)
        for handle in handles:
            user32.ShowWindow(handle, 9)
            try:
                user32.BringWindowToTop(handle)
            except Exception:
                pass
            try:
                user32.SetForegroundWindow(handle)
            except Exception:
                pass
        return bool(handles)
    except Exception:
        return False


