def _normalise_project_catalog_entries(projects) -> list[dict]:
    payload = []
    seen_ids = set()
    for item in projects or []:
        if not isinstance(item, dict):
            continue
        item_copy = dict(item)
        project_id = str(item_copy.get("ProjectId") or item_copy.get("Id") or "").strip()
        row_id = str(item_copy.get("Id") or project_id).strip()
        if not row_id and not project_id:
            continue
        canonical_id = row_id or project_id
        canonical_project_id = project_id or canonical_id
        if canonical_project_id in seen_ids:
            continue
        seen_ids.add(canonical_project_id)
        item_copy["Id"] = canonical_id
        item_copy["ProjectId"] = canonical_project_id
        item_copy["Name"] = str(item_copy.get("Name") or canonical_project_id).strip() or canonical_project_id
        payload.append(item_copy)
    return payload


def _project_catalog_quality_score(projects) -> int:
    score = 0
    for item in _normalise_project_catalog_entries(projects):
        score += 1
        for field in ("OrgId", "Stage", "SourceTenantDefaultDomainName", "TargetTenantDefaultDomainName", "Description"):
            if str(item.get(field) or "").strip():
                score += 1
    return score


def _select_preferred_project_catalog_snapshot(primary: dict | list | None, fallback: dict | list | None):
    primary_projects = primary.get("projects") if isinstance(primary, dict) else primary
    fallback_projects = fallback.get("projects") if isinstance(fallback, dict) else fallback
    primary_payload = _normalise_project_catalog_entries(primary_projects)
    fallback_payload = _normalise_project_catalog_entries(fallback_projects)
    if not fallback_payload:
        return primary
    if not primary_payload:
        return fallback
    if len(fallback_payload) > len(primary_payload):
        return fallback
    if _project_catalog_quality_score(fallback_payload) > _project_catalog_quality_score(primary_payload):
        return fallback
    return primary


def _load_project_catalog_store() -> dict:
    raw_payload = {}
    try:
        raw_payload = STATE_STORE.load_project_catalog_store(legacy_path=PROJECT_CATALOG_PATH)
    except Exception:
        raw_payload = {}
    if not isinstance(raw_payload, dict):
        raw_payload = {}
    legacy_payload = {}
    if PROJECT_CATALOG_PATH.exists():
        try:
            legacy_payload = json.loads(PROJECT_CATALOG_PATH.read_text(encoding="utf-8-sig"))
        except Exception:
            legacy_payload = {}
        if not isinstance(legacy_payload, dict):
            legacy_payload = {}
    if legacy_payload:
        merged_payload = dict(raw_payload or {})
        all_org_ids = {
            *(str(org_id or "").strip() for org_id in (raw_payload or {}).keys()),
            *(str(org_id or "").strip() for org_id in legacy_payload.keys()),
        }
        for org_id in [org for org in all_org_ids if org]:
            merged_payload[org_id] = _select_preferred_project_catalog_snapshot(
                (raw_payload or {}).get(org_id),
                legacy_payload.get(org_id),
            )
        raw_payload = merged_payload
    store = {}
    if not isinstance(raw_payload, dict):
        return store
    for org_id, snapshot in raw_payload.items():
        safe_org_id = str(org_id or "").strip()
        if not safe_org_id:
            continue
        projects = []
        updated_at = ""
        source = ""
        if isinstance(snapshot, dict):
            projects = _normalise_project_catalog_entries(snapshot.get("projects"))
            updated_at = str(snapshot.get("updated_at") or "").strip()
            source = str(snapshot.get("source") or "").strip().lower()
        elif isinstance(snapshot, list):
            projects = _normalise_project_catalog_entries(snapshot)
        if projects:
            store[safe_org_id] = {
                "projects": projects,
                "updated_at": updated_at,
                "source": source,
            }
    return store


def _save_project_catalog_store(store: dict):
    payload = {}
    for org_id, snapshot in (store or {}).items():
        safe_org_id = str(org_id or "").strip()
        if not safe_org_id or not isinstance(snapshot, dict):
            continue
        projects = _normalise_project_catalog_entries(snapshot.get("projects"))
        if not projects:
            continue
        payload[safe_org_id] = {
            "projects": projects,
            "updated_at": str(snapshot.get("updated_at") or _utc_iso_now()).strip() or _utc_iso_now(),
            "source": str(snapshot.get("source") or "").strip().lower(),
        }
    try:
        STATE_STORE.save_project_catalog_store(payload, updated_at_factory=_utc_iso_now)
    except Exception:
        pass
    try:
        PROJECT_CATALOG_PATH.parent.mkdir(parents=True, exist_ok=True)
        PROJECT_CATALOG_PATH.write_text(json.dumps(payload, indent=2), encoding="utf-8")
    except Exception:
        pass


def _project_catalog_from_live_state_dump(org_id: str) -> list[dict]:
    safe_org_id = str(org_id or "").strip()
    if not safe_org_id:
        return []
    try:
        raw_payload = json.loads(LIVE_STATE_DUMP_PATH.read_text(encoding="utf-8-sig"))
    except Exception:
        raw_payload = {}
    progress = raw_payload.get("progress_state") if isinstance(raw_payload, dict) else {}
    if not isinstance(progress, dict):
        return []
    discovered = {}
    prefix = f"{safe_org_id}:"
    for key, snapshot in progress.items():
        safe_key = str(key or "")
        if not safe_key.startswith(prefix):
            continue
        parts = safe_key.split(":", 2)
        if len(parts) < 2:
            continue
        project_id = str(parts[1] or "").strip()
        if not project_id:
            continue
        data = snapshot.get("data") if isinstance(snapshot, dict) else None
        if isinstance(data, list):
            for item in data:
                if not isinstance(item, dict):
                    continue
                details = item.get("Details") if isinstance(item.get("Details"), dict) else {}
                debug = item.get("Debug") if isinstance(item.get("Debug"), dict) else {}
                name_candidates = (
                    item.get("ProjectName"),
                    item.get("Name"),
                    details.get("Quest Name"),
                    debug.get("workloadName"),
                )
                for candidate in name_candidates:
                    safe_name = str(candidate or "").strip()
                    if safe_name:
                        discovered[project_id] = safe_name
                        break
                if project_id in discovered:
                    break
        if project_id not in discovered:
            discovered[project_id] = project_id
    return _normalise_project_catalog_entries(
        [{"Id": project_id, "ProjectId": project_id, "Name": name} for project_id, name in discovered.items()]
    )


def _saved_project_catalog_fallback(org_id: str) -> list[dict]:
    safe_org_id = str(org_id or "").strip()
    if not safe_org_id:
        return []
    derived_projects = _project_catalog_from_live_state_dump(safe_org_id)
    if derived_projects:
        return derived_projects
    return []


def _cleanup_stale_interactive_auth_hosts(current_pid: int | None = None) -> int:
    if os.name != "nt":
        return 0
    safe_current_pid = int(current_pid or 0)
    try:
        user32 = ctypes.windll.user32
        matching_pids = set()
        title_tokens = (
            "sign in to your account",
            "pick an account",
            "enter password",
            "work or school account",
            "stay signed in",
            "more information required",
            "approve sign in request",
        )

        @ctypes.WINFUNCTYPE(ctypes.c_bool, ctypes.c_void_p, ctypes.c_void_p)
        def enum_windows(hwnd, _lparam):
            if not user32.IsWindowVisible(hwnd):
                return True
            length = user32.GetWindowTextLengthW(hwnd)
            if length <= 0:
                return True
            buffer = ctypes.create_unicode_buffer(length + 1)
            user32.GetWindowTextW(hwnd, buffer, len(buffer))
            title = str(buffer.value or "").strip()
            if not title:
                return True
            normalised = title.lower()
            if not any(token in normalised for token in title_tokens):
                return True
            process_id = ctypes.c_ulong()
            user32.GetWindowThreadProcessId(hwnd, ctypes.byref(process_id))
            pid = int(process_id.value or 0)
            if pid > 0:
                matching_pids.add(pid)
            return True

        user32.EnumWindows(enum_windows, 0)
        terminated = 0
        for pid in sorted(matching_pids):
            if pid <= 0 or pid == safe_current_pid:
                continue
            try:
                proc = subprocess.run(
                    [
                        "powershell.exe",
                        "-NoProfile",
                        "-Command",
                        f"(Get-Process -Id {pid} -ErrorAction Stop).ProcessName",
                    ],
                    capture_output=True,
                    text=True,
                    check=False,
                    timeout=5,
                )
                process_name = str(proc.stdout or "").strip().lower()
            except Exception:
                process_name = ""
            if process_name not in {"powershell", "pwsh"}:
                continue
            try:
                subprocess.run(
                    ["taskkill", "/PID", str(pid), "/T", "/F"],
                    capture_output=True,
                    text=True,
                    check=False,
                    timeout=10,
                )
                terminated += 1
            except Exception:
                continue
        return terminated
    except Exception:
        return 0


def _default_preferences():
    return {
        "region": "EU",
        "scope": "exchange",
        "refreshRate": "0",
        "theme": "light",
        "lastOrgId": "",
        "savedOrgIds": [],
        "projectsByOrg": {},
        "collapsedSections": {},
    }


def _normalise_preferences(payload):
    defaults = _default_preferences()
    incoming = payload if isinstance(payload, dict) else {}
    exclude_selftest = not SELFTEST_MODE

    saved_org_ids = []
    seen_orgs = set()
    for value in incoming.get("savedOrgIds", []):
        org_id = str(value or "").strip()
        if exclude_selftest and org_id == SELFTEST_ORG_ID:
            continue
        if not org_id or org_id in seen_orgs:
            continue
        seen_orgs.add(org_id)
        saved_org_ids.append(org_id)
        if len(saved_org_ids) >= ORG_HISTORY_LIMIT:
            break

    projects_by_org = {}
    raw_projects = incoming.get("projectsByOrg", {})
    if isinstance(raw_projects, dict):
        for org_id, project_id in raw_projects.items():
            safe_org_id = str(org_id or "").strip()
            safe_project_id = str(project_id or "").strip()
            if exclude_selftest and (safe_org_id == SELFTEST_ORG_ID or safe_project_id == SELFTEST_PROJECT_ID):
                continue
            if safe_org_id and safe_project_id:
                projects_by_org[safe_org_id] = safe_project_id

    collapsed_sections = {}
    raw_sections = incoming.get("collapsedSections", {})
    if isinstance(raw_sections, dict):
        for section_id, collapsed in raw_sections.items():
            safe_section_id = str(section_id or "").strip()
            if safe_section_id:
                collapsed_sections[safe_section_id] = bool(collapsed)

    normalised = {
        "region": str(incoming.get("region") or defaults["region"]).strip().upper() or defaults["region"],
        "scope": _normalise_stream(incoming.get("scope") or defaults["scope"]),
        "refreshRate": str(incoming.get("refreshRate") or defaults["refreshRate"]).strip() or defaults["refreshRate"],
        "theme": str(incoming.get("theme") or defaults["theme"]).strip().lower() or defaults["theme"],
        "lastOrgId": str(incoming.get("lastOrgId") or "").strip(),
        "savedOrgIds": saved_org_ids,
        "projectsByOrg": projects_by_org,
        "collapsedSections": collapsed_sections,
    }

    if normalised["theme"] not in {"light", "dark"}:
        normalised["theme"] = defaults["theme"]

    last_org_id = normalised["lastOrgId"]
    if exclude_selftest and last_org_id == SELFTEST_ORG_ID:
        last_org_id = ""
        normalised["lastOrgId"] = ""
    if last_org_id:
        normalised["savedOrgIds"] = [last_org_id] + [org_id for org_id in normalised["savedOrgIds"] if org_id != last_org_id]
        normalised["savedOrgIds"] = normalised["savedOrgIds"][:ORG_HISTORY_LIMIT]
    else:
        normalised["savedOrgIds"] = normalised["savedOrgIds"][:ORG_HISTORY_LIMIT]

    return normalised


def _load_preferences():
    with preferences_lock:
        try:
            if PREFERENCES_PATH.exists():
                raw_data = json.loads(PREFERENCES_PATH.read_text(encoding="utf-8"))
                normalised = _normalise_preferences(raw_data)
                if normalised != raw_data:
                    PREFERENCES_PATH.write_text(json.dumps(normalised, indent=2), encoding="utf-8")
                return normalised
        except (OSError, json.JSONDecodeError):
            pass
    return _default_preferences()


def _save_preferences(preferences):
    normalised = _normalise_preferences(preferences)
    with preferences_lock:
        PREFERENCES_PATH.parent.mkdir(parents=True, exist_ok=True)
        PREFERENCES_PATH.write_text(json.dumps(normalised, indent=2), encoding="utf-8")
    return normalised


def _default_history_store():
    return {
        "version": 1,
        "workloads": {},
        "projects": {},
    }


def _normalise_history_store(raw_store: dict | None) -> dict:
    metrics_builder = globals().get("_build_onedrive_progress_metrics")
    if not callable(metrics_builder):
        try:
            from workload_metrics import build_onedrive_progress_metrics as metrics_builder
        except Exception:
            metrics_builder = None

    def _history_number(value):
        if value is None or value == "":
            return None
        if isinstance(value, bool):
            return int(value)
        if isinstance(value, (int, float)):
            return value
        if isinstance(value, str):
            cleaned = value.strip().replace(",", "")
            if not cleaned:
                return None
            try:
                number = float(cleaned)
            except ValueError:
                return None
            return int(number) if number.is_integer() else number
        return None

    safe_store = raw_store if isinstance(raw_store, dict) else {}
    workloads = safe_store.get("workloads") if isinstance(safe_store.get("workloads"), dict) else {}
    projects = safe_store.get("projects") if isinstance(safe_store.get("projects"), dict) else {}
    normalised_workloads = {}
    for key, entries in workloads.items():
        if not isinstance(entries, list):
            continue
        fixed_entries = []
        for entry in entries:
            if not isinstance(entry, dict):
                continue
            fixed = dict(entry)
            display_type = str(fixed.get("displayType") or "").strip().lower()
            total_objects = int(_history_number(fixed.get("totalObjects")) or 0)
            completed_objects = int(_history_number(fixed.get("completedObjects")) or 0)
            migrated_bytes_direct = bool(fixed.get("migratedBytesDirect"))
            if total_objects > 0:
                if display_type in {"teams", "m365 groups"}:
                    fixed["completionPercent"] = round((completed_objects / total_objects) * 100, 1)
                elif display_type == "onedrive":
                    status_breakdown = fixed.get("statusBreakdown") if isinstance(fixed.get("statusBreakdown"), dict) else {}
                    if status_breakdown and callable(metrics_builder):
                        metrics = metrics_builder(
                            status_breakdown,
                            exclude_not_migratable_from_scope=bool(fixed.get("excludeNotMigratableFromScope")),
                        )
                        fixed["totalObjects"] = int(metrics["inScopeTotal"])
                        fixed["completedObjects"] = int(metrics["completedObjects"])
                        fixed["activeObjects"] = int(metrics["activeObjects"])
                        fixed["pendingObjects"] = int(metrics["pendingObjects"])
                        fixed["issueObjects"] = int(metrics["issueObjects"])
                        fixed["completionPercent"] = round(metrics["completionPercent"], 1)
                        fixed["statusCompletionPercent"] = round(metrics["healthyCompletionPercent"], 1)
                        fixed["completedWithIssuesPercent"] = round(metrics["completedWithIssuesPercent"], 1)
                        fixed["partialPercent"] = round(metrics["partialPercent"], 1)
                        fixed["activePercent"] = round(metrics["activePercent"], 1)
                        fixed["blockedPercent"] = round(metrics["blockedPercent"], 1)
                        fixed["notStartedPercent"] = round(metrics["notStartedPercent"], 1)
                        fixed["exceptionPercent"] = round(metrics["exceptionPercent"], 1)
                        fixed["healthyCompletedObjects"] = int(metrics["healthyCompletedObjects"])
                        fixed["completedWithIssuesObjects"] = int(metrics["completedWithIssuesObjects"])
                        fixed["partialObjects"] = int(metrics["partialObjects"])
                        fixed["blockedObjects"] = int(metrics["blockedObjects"])
                        fixed["notStartedObjects"] = int(metrics["notStartedObjects"])
                        fixed["exceptionObjects"] = int(metrics["exceptionObjects"])
                    elif not migrated_bytes_direct:
                        fixed["completionPercent"] = round((completed_objects / total_objects) * 100, 1)
            fixed_entries.append(fixed)
        normalised_workloads[str(key)] = fixed_entries
    return {
        "version": 1,
        "workloads": normalised_workloads,
        "projects": projects,
    }


def _load_history_store():
    try:
        return STATE_STORE.load_history_store(
            legacy_path=HISTORY_PATH,
            normalizer=_normalise_history_store,
            default_factory=_default_history_store,
        )
    except Exception:
        pass
    try:
        if HISTORY_PATH.exists():
            raw = json.loads(HISTORY_PATH.read_text(encoding="utf-8"))
            if isinstance(raw, dict):
                return _normalise_history_store(raw)
    except (OSError, json.JSONDecodeError):
        pass
    return _default_history_store()


history_store = _load_history_store()


def _default_remediation_store():
    return {
        "version": 2,
        "snapshots": {},
        "issueSlices": {},
    }


def _load_remediation_store():
    try:
        return STATE_STORE.load_remediation_store(
            legacy_path=REMEDIATION_CACHE_PATH,
            max_legacy_bytes=REMEDIATION_CACHE_MAX_BYTES,
            default_factory=_default_remediation_store,
        )
    except Exception:
        pass
    try:
        if REMEDIATION_CACHE_PATH.exists():
            if REMEDIATION_CACHE_MAX_BYTES > 0 and REMEDIATION_CACHE_PATH.stat().st_size > REMEDIATION_CACHE_MAX_BYTES:
                return _default_remediation_store()
            raw = json.loads(REMEDIATION_CACHE_PATH.read_text(encoding="utf-8-sig"))
            if isinstance(raw, dict):
                return {
                    "version": 2,
                    "snapshots": raw.get("snapshots", {}) if isinstance(raw.get("snapshots"), dict) else {},
                    "issueSlices": raw.get("issueSlices", {}) if isinstance(raw.get("issueSlices"), dict) else {},
                }
    except (OSError, json.JSONDecodeError):
        pass
    return _default_remediation_store()


remediation_store = _load_remediation_store()


def _json_safe(value):
    if isinstance(value, dict):
        return {str(key): _json_safe(item) for key, item in value.items()}
    if isinstance(value, (list, tuple)):
        return [_json_safe(item) for item in value]
    if isinstance(value, set):
        return [_json_safe(item) for item in sorted(value, key=lambda item: str(item))]
    return value


def _json_size_bytes(value) -> int:
    try:
        return len(json.dumps(value, separators=(",", ":"), ensure_ascii=False).encode("utf-8"))
    except Exception:
        return 0


def _remediation_store_snapshot_locked() -> dict:
    return _json_safe({
        "version": 2,
        "snapshots": copy.deepcopy(remediation_store.get("snapshots", {}) if isinstance(remediation_store.get("snapshots"), dict) else {}),
        "issueSlices": copy.deepcopy(remediation_store.get("issueSlices", {}) if isinstance(remediation_store.get("issueSlices"), dict) else {}),
    })


def _trim_remediation_store_locked():
    if REMEDIATION_CACHE_MAX_BYTES <= 0:
        return
    remediation_store.setdefault("snapshots", {})
    remediation_store.setdefault("issueSlices", {})
    while _json_size_bytes(_remediation_store_snapshot_locked()) > REMEDIATION_CACHE_MAX_BYTES:
        candidates = []
        for namespace_name, entries in (
            ("issueSlices", remediation_store.get("issueSlices", {})),
            ("snapshots", remediation_store.get("snapshots", {})),
        ):
            if not isinstance(entries, dict):
                continue
            for cache_key, entry in list(entries.items()):
                generated_at = str(entry.get("generatedAt") or "").strip() if isinstance(entry, dict) else ""
                candidates.append((0 if namespace_name == "issueSlices" else 1, generated_at, -_json_size_bytes(entry), namespace_name, cache_key))
        if not candidates:
            remediation_store["snapshots"] = {}
            remediation_store["issueSlices"] = {}
            break
        _, _, _, namespace_name, cache_key = sorted(candidates)[0]
        remediation_store.get(namespace_name, {}).pop(cache_key, None)


def _cache_remediation_entry(namespace_name: str, cache_key: str, entry: dict) -> bool:
    safe_namespace = str(namespace_name or "").strip()
    safe_cache_key = str(cache_key or "").strip()
    if safe_namespace not in {"snapshots", "issueSlices"} or not safe_cache_key or not isinstance(entry, dict) or not entry:
        return False
    safe_entry = _json_safe(copy.deepcopy(entry))
    if REMEDIATION_CACHE_MAX_BYTES > 0 and _json_size_bytes(safe_entry) > REMEDIATION_CACHE_MAX_BYTES:
        return False
    with remediation_cache_lock:
        remediation_store.setdefault(safe_namespace, {})
        remediation_store[safe_namespace][safe_cache_key] = safe_entry
        _trim_remediation_store_locked()
    _persist_remediation_store()
    return True


def _persist_remediation_store():
    with remediation_cache_lock:
        snapshot = _remediation_store_snapshot_locked()
    try:
        STATE_STORE.save_remediation_store(
            snapshot,
            updated_at_factory=_utc_iso_now,
            max_payload_bytes=REMEDIATION_CACHE_MAX_BYTES,
        )
    except Exception:
        pass
    try:
        encoded = json.dumps(snapshot, indent=2, ensure_ascii=False).encode("utf-8")
        if REMEDIATION_CACHE_MAX_BYTES > 0 and len(encoded) > REMEDIATION_CACHE_MAX_BYTES:
            return
        REMEDIATION_CACHE_PATH.parent.mkdir(parents=True, exist_ok=True)
        REMEDIATION_CACHE_PATH.write_bytes(encoded)
    except (OSError, TypeError, ValueError):
        pass


def _remediation_cache_key(org_id: str, project_id: str, scope: str) -> str:
    return f"{str(org_id or '').strip()}::{str(project_id or '').strip()}::{_normalise_stream(scope or 'all')}"


def _load_cached_remediation_snapshot(org_id: str, project_id: str, scope: str = "all"):
    cache_key = _remediation_cache_key(org_id, project_id, scope)
    with remediation_cache_lock:
        raw = copy.deepcopy(remediation_store.get("snapshots", {}).get(cache_key))
    if not isinstance(raw, dict):
        return None
    payload = raw.get("payload")
    if not isinstance(payload, dict) or not payload:
        return None
    payload.setdefault("generatedAt", raw.get("generatedAt"))
    payload["cacheSource"] = "persisted"
    payload["cacheKey"] = cache_key
    return payload


def _cache_remediation_snapshot(org_id: str, project_id: str, scope: str, payload: dict):
    if not org_id or not project_id or not isinstance(payload, dict) or not payload:
        return
    scope = _normalise_stream(scope or "all")
    cache_key = _remediation_cache_key(org_id, project_id, scope)
    _cache_remediation_entry("snapshots", cache_key, {
        "orgId": str(org_id or "").strip(),
        "projectId": str(project_id or "").strip(),
        "scope": scope,
        "generatedAt": str(payload.get("generatedAt") or _history_iso_now()),
        "payload": payload,
    })


def _invalidate_remediation_snapshot(org_id: str, project_id: str, scope: str = "all"):
    cache_key = _remediation_cache_key(org_id, project_id, scope)
    removed = False
    with remediation_cache_lock:
        snapshots = remediation_store.setdefault("snapshots", {})
        removed = cache_key in snapshots
        snapshots.pop(cache_key, None)
    if removed:
        _persist_remediation_store()


def _invalidate_remediation_project_snapshots(org_id: str, project_id: str):
    prefix = f"{str(org_id or '').strip()}::{str(project_id or '').strip()}::"
    removed = False
    with remediation_cache_lock:
        snapshots = remediation_store.setdefault("snapshots", {})
        for key in [key for key in snapshots if key.startswith(prefix)]:
            snapshots.pop(key, None)
            removed = True
    if removed:
        _persist_remediation_store()


def _remediation_issue_cache_key(org_id: str, project_id: str, workload: str, state: str) -> str:
    return f"{str(org_id or '').strip()}::{str(project_id or '').strip()}::{str(workload or '').strip().lower()}::{str(state or '').strip().lower()}"


def _load_cached_remediation_issue_payload(org_id: str, project_id: str, workload: str, state: str):
    cache_key = _remediation_issue_cache_key(org_id, project_id, workload, state)
    with remediation_cache_lock:
        raw = copy.deepcopy(remediation_store.get("issueSlices", {}).get(cache_key))
    if not isinstance(raw, dict):
        return None
    payload = raw.get("payload")
    if not isinstance(payload, dict) or not payload:
        return None
    if not isinstance(payload.get("rows"), list) and isinstance(payload.get("events"), list):
        payload["rows"] = copy.deepcopy(payload.get("events") or [])
    payload.setdefault("generatedAt", raw.get("generatedAt"))
    payload["cacheSource"] = "persisted"
    payload["cacheKey"] = cache_key
    return payload


def _cache_remediation_issue_payload(org_id: str, project_id: str, workload: str, state: str, payload: dict):
    if not org_id or not project_id or not workload or not state or not isinstance(payload, dict) or not payload:
        return
    cache_key = _remediation_issue_cache_key(org_id, project_id, workload, state)
    _cache_remediation_entry("issueSlices", cache_key, {
        "orgId": str(org_id or "").strip(),
        "projectId": str(project_id or "").strip(),
        "workload": str(workload or "").strip(),
        "state": str(state or "").strip(),
        "generatedAt": str(payload.get("generatedAt") or _history_iso_now()),
        "payload": payload,
    })


def _invalidate_remediation_issue_payload(org_id: str, project_id: str, workload: str, state: str):
    cache_key = _remediation_issue_cache_key(org_id, project_id, workload, state)
    removed = False
    with remediation_cache_lock:
        slices = remediation_store.setdefault("issueSlices", {})
        removed = cache_key in slices
        slices.pop(cache_key, None)
    if removed:
        _persist_remediation_store()


def _invalidate_remediation_issue_project_payloads(org_id: str, project_id: str, workload: str | None = None):
    project_prefix = f"{str(org_id or '').strip()}::{str(project_id or '').strip()}::"
    workload_prefix = f"{project_prefix}{str(workload or '').strip().lower()}::" if workload else None
    removed = False
    with remediation_cache_lock:
        slices = remediation_store.setdefault("issueSlices", {})
        if workload_prefix:
            keys = [key for key in slices if key.startswith(workload_prefix)]
        else:
            keys = [key for key in slices if key.startswith(project_prefix)]
        for key in keys:
            slices.pop(key, None)
            removed = True
    if removed:
        _persist_remediation_store()


def _persist_history_store():
    with history_lock:
        snapshot = copy.deepcopy(history_store)
    try:
        STATE_STORE.save_history_store(snapshot, updated_at_factory=_utc_iso_now)
    except Exception:
        pass
    try:
        HISTORY_PATH.parent.mkdir(parents=True, exist_ok=True)
        HISTORY_PATH.write_text(json.dumps(snapshot, indent=2), encoding="utf-8")
    except OSError:
        pass


def _history_workload_key(org_id: str, project_id: str, display_type: str) -> str:
    return f"{str(org_id or '').strip()}::{str(project_id or '').strip()}::{str(display_type or '').strip().lower()}"


def _history_project_key(org_id: str, project_id: str) -> str:
    return f"{str(org_id or '').strip()}::{str(project_id or '').strip()}"


def _utc_now():
    return datetime.now(timezone.utc)


def _utc_now_naive():
    return _utc_now().replace(tzinfo=None)


def _utc_iso_now() -> str:
    return _utc_now().isoformat().replace("+00:00", "Z")


def _history_iso_now() -> str:
    return _utc_iso_now()


def _parse_history_iso(value):
    text = str(value or "").strip()
    if not text:
        return None
    try:
        return datetime.fromisoformat(text.replace("Z", "+00:00"))
    except ValueError:
        return None


def _format_history_age(seconds: float | int | None) -> str:
    numeric = float(seconds or 0)
    if numeric <= 5:
        return "just now"
    if numeric < 60:
        return f"{int(round(numeric))} sec ago"
    if numeric < 3600:
        return f"{int(round(numeric / 60))} min ago"
    if numeric < 86400:
        hours = numeric / 3600
        return f"{hours:.1f} hr ago" if hours < 10 else f"{int(round(hours))} hr ago"
    days = numeric / 86400
    return f"{days:.1f} d ago" if days < 10 else f"{int(round(days))} d ago"


def _safe_history_number(value):
    parsed = _parse_number(value)
    if parsed is None:
        return None
    if float(parsed).is_integer():
        return int(parsed)
    return round(float(parsed), 3)


def _migrated_data_accuracy(summary: dict) -> str:
    return _telemetry_migrated_data_accuracy(summary)


def _migrated_data_is_estimated(summary: dict) -> bool:
    return _telemetry_migrated_data_is_estimated(summary)


def _direct_migrated_bytes(summary: dict):
    return _telemetry_direct_migrated_bytes(summary)


def _history_direct_migrated_bytes(entry: dict):
    return _telemetry_history_direct_migrated_bytes(entry)


def _make_workload_history_entry(summary: dict, stream: str, captured_at: str | None = None):
    display_type = str(summary.get("DisplayType") or summary.get("Type") or "Quest").strip() or "Quest"
    overview = summary.get("Overview") or _build_workload_overview(summary)
    status_breakdown = summary.get("StatusBreakdown") or {}
    direct_migrated_bytes = _safe_history_number(_direct_migrated_bytes(summary))
    return {
        "capturedAt": captured_at or _history_iso_now(),
        "stream": _normalise_stream(stream),
        "displayType": display_type,
        "status": str(summary.get("DisplayStatus") or summary.get("Status") or "Unknown"),
        "totalObjects": int(_parse_number(overview.get("totalObjects")) or 0),
        "completedObjects": int(_parse_number(overview.get("completedObjects")) or 0),
        "activeObjects": int(_parse_number(overview.get("activeObjects")) or 0),
        "pendingObjects": int(_parse_number(overview.get("pendingObjects")) or 0),
        "issueObjects": int(_parse_number(overview.get("issueObjects")) or 0),
        "completionPercent": float(_parse_number(overview.get("completionPercent")) or 0),
        "objectCompletionPercent": float(_parse_number(overview.get("objectCompletionPercent")) or 0),
        "completionBasis": str(overview.get("completionBasis") or "objects"),
        "sourceBytes": _safe_history_number(_parse_number(overview.get("sourceBytes"))),
        "migratedBytes": direct_migrated_bytes,
        "migratedBytesDirect": direct_migrated_bytes is not None,
        "throughputBytesPerHour": _safe_history_number(overview.get("throughputBytesPerHour")),
        "statusBreakdown": {
            str(label): int(_parse_number(value) or 0)
            for label, value in status_breakdown.items()
            if int(_parse_number(value) or 0) > 0
        },
    }


def _latest_workload_history_entry(org_id: str, project_id: str, display_type: str):
    key = _history_workload_key(org_id, project_id, display_type)
    with history_lock:
        entries = copy.deepcopy(history_store.get("workloads", {}).get(key, []))
    return entries[-1] if entries else None


def _get_workload_history_entries(org_id: str, project_id: str, display_type: str):
    key = _history_workload_key(org_id, project_id, display_type)
    with history_lock:
        entries = copy.deepcopy(history_store.get("workloads", {}).get(key, []))
    return entries


def _latest_project_history_entry(org_id: str, project_id: str):
    key = _history_project_key(org_id, project_id)
    with history_lock:
        entries = copy.deepcopy(history_store.get("projects", {}).get(key, []))
    return entries[-1] if entries else None


def _get_project_history_entries(org_id: str, project_id: str):
    key = _history_project_key(org_id, project_id)
    with history_lock:
        entries = copy.deepcopy(history_store.get("projects", {}).get(key, []))
    return entries


