def _order_breakdown(breakdown: dict | None, preferred_order, include_missing: bool = False) -> dict:
    breakdown = breakdown or {}
    ordered = {}
    remaining = {str(label): int(count) for label, count in breakdown.items()}

    for label in preferred_order:
        if label in remaining:
            ordered[label] = remaining.pop(label)
        elif include_missing:
            ordered[label] = 0

    for label, count in sorted(remaining.items(), key=lambda entry: (-entry[1], entry[0].lower())):
        ordered[label] = count

    return ordered


def _is_quest_mailbox_state_breakdown(breakdown: dict | None) -> bool:
    if not breakdown:
        return False
    known = set(_QUEST_MAILBOX_STATES)
    return all(str(label) in known for label in breakdown.keys())


