@app.get("/api/remediation")
def get_remediation(org_id: str, project_id: str, scope: str = "all", force: bool = False):
    scope = _normalise_stream(scope or "all")
    _require_quest_session(org_id)
    if force:
        _invalidate_remediation_issue_project_payloads(org_id, project_id)
    jobs = _prefetch_remediation_issue_slices(org_id, project_id, scope=scope, force=force, priority="background")
    payload = _cached_remediation_issue_family_payload(org_id, project_id, scope) or _empty_remediation_payload(scope, warming=bool(jobs))
    ready_issue_slices = int(payload.get("issueSliceReadyCount") or 0)
    total_issue_slices = int(payload.get("issueSliceCount") or len(jobs))
    if total_issue_slices > 0:
        payload["warming"] = ready_issue_slices < total_issue_slices
        payload["partial"] = 0 < ready_issue_slices < total_issue_slices
        payload["percent"] = 100 if ready_issue_slices >= total_issue_slices else max(1, int((ready_issue_slices / max(total_issue_slices, 1)) * 100))
        payload["message"] = (
            f"Loaded the latest {_stream_label(scope)} remediation view."
            if ready_issue_slices >= total_issue_slices
            else f"Warming the {_stream_label(scope)} remediation issue cache in the background."
        )
    else:
        payload["warming"] = False
        payload["partial"] = False
        payload["percent"] = 100 if payload.get("workloadCount") else 0
        payload["message"] = (
            f"Loaded the latest {_stream_label(scope)} remediation view."
            if payload.get("workloadCount")
            else f"No actionable {_stream_label(scope)} remediation issues are currently available."
        )
    return payload


