@app.get("/api/remediation/issues")
def get_remediation_issue_slice(org_id: str, project_id: str, workload: str, state: str, scope: str = "", force: bool = False):
    _require_quest_session(org_id)
    workload = str(workload or "").strip()
    state = str(state or "").strip()
    scope = _canonical_drilldown_stream(scope, workload)
    if not workload or not state:
        raise HTTPException(status_code=400, detail="Workload and Quest state are required for remediation issue slices.")
    try:
        progress_key = _remediation_issue_progress_key(org_id, project_id, workload, state)
        if force:
            _invalidate_remediation_issue_payload(org_id, project_id, workload, state)
            _invalidate_progress_key(progress_key)
        state_count = _remediation_issue_expected_count(org_id, project_id, scope, workload, state)
        payload = None if force else _load_cached_remediation_issue_payload(org_id, project_id, workload, state)
        if _remediation_issue_payload_is_stale(payload, state_count):
            _invalidate_remediation_issue_payload(org_id, project_id, workload, state)
            payload = None
        snapshot = _get_progress_snapshot(progress_key)
        snapshot_payload = snapshot.get("data") if (not force and isinstance(snapshot.get("data"), dict)) else None
        if _remediation_issue_payload_is_stale(snapshot_payload, state_count):
            snapshot_payload = None
        if isinstance(snapshot_payload, dict) and snapshot_payload:
            _cache_remediation_issue_payload(org_id, project_id, workload, state, snapshot_payload)
            return snapshot_payload
        if isinstance(payload, dict) and payload:
            return payload
        direct_payload = None
        cached_event_payload = _cached_remediation_payload(org_id, project_id, scope)
        cached_rows = _cached_drilldown_rows(org_id, project_id, scope, workload, state)
        has_cached_events = isinstance(cached_event_payload, dict) and isinstance(cached_event_payload.get("events"), list)
        usable_cached_events = has_cached_events and (bool(cached_event_payload.get("events")) or state_count <= 0)
        has_cached_rows = isinstance(cached_rows, list)
        usable_cached_rows = has_cached_rows and (bool(cached_rows) or state_count <= 0)
        if SELFTEST_MODE or usable_cached_events or usable_cached_rows:
            direct_payload = _build_remediation_issue_payload(
                org_id,
                project_id,
                workload=workload,
                state=state,
                scope=scope,
                force=force,
                progress_key=progress_key,
                allow_live_drilldown=False,
            )
        if _remediation_issue_payload_is_stale(direct_payload, state_count):
            direct_payload = None
        if direct_payload is None and state_count > 0:
            direct_payload = _build_remediation_issue_payload(
                org_id,
                project_id,
                workload=workload,
                state=state,
                scope=scope,
                force=force,
                progress_key=progress_key,
                allow_live_drilldown=True,
            )
        if _remediation_issue_payload_is_stale(direct_payload, state_count):
            direct_payload = None
        if isinstance(direct_payload, dict) and direct_payload:
            _cache_remediation_issue_payload(org_id, project_id, workload, state, direct_payload)
            _store_progress_result(
                progress_key,
                "done",
                direct_payload.get("message") or f"Loaded the current {workload} remediation issue slice.",
                direct_payload,
                percent=100,
            )
            return direct_payload
        snapshot = _queue_remediation_issue_job(
            org_id,
            project_id,
            workload=workload,
            state=state,
            scope=scope,
            force=force,
            priority="interactive",
            count=state_count,
        )
        queued_payload = snapshot.get("data") if isinstance(snapshot.get("data"), dict) else None
        if snapshot.get("status") == "done" and isinstance(queued_payload, dict) and queued_payload:
            _cache_remediation_issue_payload(org_id, project_id, workload, state, queued_payload)
            return queued_payload
        return {
            "generatedAt": _history_iso_now(),
            "scope": scope,
            "workload": workload,
            "state": state,
            "contextState": state,
            "rowCount": 0,
            "clusterCount": 0,
            "affectedObjectCount": state_count,
            "categories": [],
            "severities": [],
            "clusters": [],
            "rows": [],
            "warming": True,
            "message": snapshot.get("message") or f"Building the {workload} {state} remediation issue slice in the background.",
            "percent": snapshot.get("percent") or 1,
        }
    except HTTPException:
        raise
    except Exception as exc:
        raise HTTPException(status_code=500, detail=_friendly_quest_error(exc))


@app.get("/api/remediation/issues/progress")
def get_remediation_issue_slice_progress(org_id: str, project_id: str, workload: str, state: str):
    if not SELFTEST_MODE and not _quest_session_is_connected():
        return _disconnected_progress_payload("Quest is not connected. Sign in again before loading remediation issue progress.")
    workload = str(workload or "").strip()
    state = str(state or "").strip()
    if not workload or not state:
        raise HTTPException(status_code=400, detail="Workload and Quest state are required for remediation issue slice progress.")
    scope = _canonical_drilldown_stream("", workload)
    expected_count = _remediation_issue_expected_count(org_id, project_id, scope, workload, state)
    cached = _load_cached_remediation_issue_payload(org_id, project_id, workload, state)
    if _remediation_issue_payload_is_stale(cached, expected_count):
        _invalidate_remediation_issue_payload(org_id, project_id, workload, state)
        cached = None
    snapshot = _get_progress_snapshot(_remediation_issue_progress_key(org_id, project_id, workload, state))
    status = str(snapshot.get("status") or "idle").strip().lower()
    snapshot_payload = snapshot.get("data") if isinstance(snapshot.get("data"), dict) else None
    if _remediation_issue_payload_is_stale(snapshot_payload, expected_count):
        snapshot_payload = None
    if isinstance(snapshot_payload, dict) and snapshot_payload:
        _cache_remediation_issue_payload(org_id, project_id, workload, state, snapshot_payload)
        return {
            "status": "done",
            "message": f"Loaded the latest {workload} {state} remediation issue slice.",
            "percent": 100,
            "data": snapshot_payload,
        }
    if isinstance(cached, dict) and cached:
        return {
            "status": "done",
            "message": f"Loaded the cached {workload} {state} remediation issue slice.",
            "percent": 100,
            "data": cached,
        }
    if status in {"running", "error", "done"}:
        return snapshot
    return {
        "status": "idle",
        "message": f"No cached {workload} {state} remediation issue slice is available yet.",
        "percent": 0,
        "data": {},
    }


@app.get("/api/remediation/events")
def get_remediation_events(org_id: str, project_id: str, workload: str = "", object_id: str = "", object_ids: str = ""):
    _require_quest_session(org_id)
    combined_ids = []
    if object_id:
        combined_ids.extend(part.strip() for part in str(object_id).split(","))
    if object_ids:
        combined_ids.extend(part.strip() for part in str(object_ids).split(","))
    combined_ids = [value for value in combined_ids if value]
    if not combined_ids:
        raise HTTPException(status_code=400, detail="At least one object ID is required to load Quest remediation events.")
    try:
        return fetch_remediation_events_for_objects(org_id, project_id, combined_ids, workload=workload)
    except HTTPException:
        raise
    except Exception as exc:
        raise HTTPException(status_code=500, detail=_friendly_quest_error(exc))


@app.post("/api/remediation/acknowledge")
async def post_remediation_acknowledge(request: Request):
    try:
        payload = await request.json()
    except Exception as exc:
        raise HTTPException(status_code=400, detail=f"Invalid acknowledge payload: {exc}")

    org_id = str(payload.get("org_id") or "").strip()
    project_id = str(payload.get("project_id") or "").strip()
    scope = _normalise_stream(payload.get("scope") or "all")
    workload = str(payload.get("workload") or "").strip()
    event_ids = payload.get("event_ids") or []
    object_ids = payload.get("object_ids") or []
    if not org_id or not project_id:
        raise HTTPException(status_code=400, detail="Organization ID and project ID are required.")
    _require_quest_session(org_id)
    try:
        result = acknowledge_remediation_events(org_id, project_id, event_ids, object_ids=object_ids, workload=workload)
    except HTTPException:
        raise
    except Exception as exc:
        raise HTTPException(status_code=500, detail=_friendly_quest_error(exc))

    # Always clear the scoped remediation cache so the next read reflects Quest's latest event posture.
    _invalidate_progress_key(_remediation_progress_key(org_id, project_id, scope))
    _invalidate_progress_key(_remediation_progress_key(org_id, project_id, "all"))
    _invalidate_remediation_snapshot(org_id, project_id, scope)
    _invalidate_remediation_snapshot(org_id, project_id, "all")
    if workload:
        _invalidate_remediation_issue_project_payloads(org_id, project_id, workload=workload)
    else:
        _invalidate_remediation_issue_project_payloads(org_id, project_id)
    return result


@app.get("/api/workloads")
def get_workloads(org_id: str, project_id: str, stream: str = "exchange", force: bool = False):
    stream = _normalise_stream(stream)
    _require_quest_session(org_id)
    key = _progress_key(org_id, project_id, stream)
    if force:
        _invalidate_workload_cache(org_id, project_id, stream=stream)
    state = _get_progress_snapshot(key)
    cached = None if force else _cached_workload_data(org_id, project_id, stream)
    if isinstance(cached, list) and cached:
        if not SELFTEST_MODE and stream in (*REMEDIATION_PREFETCH_SCOPES, "all"):
            try:
                _prefetch_remediation_issue_slices(org_id, project_id, scope=stream, force=False, priority="background")
            except Exception:
                pass
        return _decorate_workload_payload(org_id, project_id, stream, cached, response_source="cache")
    if not force and state.get("status") == "done" and isinstance(state.get("data"), list):
        if not SELFTEST_MODE and stream in (*REMEDIATION_PREFETCH_SCOPES, "all"):
            try:
                _prefetch_remediation_issue_slices(org_id, project_id, scope=stream, force=False, priority="background")
            except Exception:
                pass
        return _decorate_workload_payload(org_id, project_id, stream, state.get("data", []), response_source="cache")
    if state.get("status") == "running" and _worker_is_alive(key):
        return HTMLResponse(
            content=json.dumps({
                "status": "running",
                "message": state.get("message"),
                "percent": state.get("percent"),
            }),
            status_code=202,
            media_type="application/json",
        )
    state = _start_workload_job(org_id, project_id, stream=stream, force=force)
    return HTMLResponse(
        content=json.dumps({
            "status": state.get("status"),
            "message": state.get("message"),
            "percent": state.get("percent"),
        }),
        status_code=202,
        media_type="application/json",
    )


@app.get("/api/drilldown")
def get_drilldown(org_id: str, project_id: str, stream: str = "exchange", workload: str = "", state: str = "", background: bool = False):
    _require_quest_session(org_id)
    stream = _canonical_drilldown_stream(stream, workload)
    workload = str(workload or "").strip()
    raw_state = str(state or "").strip()
    key = _drilldown_progress_key(org_id, project_id, stream, workload, raw_state)
    snapshot = _get_progress_snapshot(key)
    if isinstance(snapshot.get("data"), list) and snapshot.get("data"):
        return snapshot.get("data", [])
    if snapshot.get("status") == "done" and isinstance(snapshot.get("data"), list) and (snapshot.get("data") or not workload or not raw_state):
        return snapshot.get("data", [])
    if snapshot.get("status") == "running" and _worker_is_alive(key):
        return HTMLResponse(
            content=json.dumps({
                "status": "running",
                "message": snapshot.get("message"),
                "percent": snapshot.get("percent"),
            }),
            status_code=202,
            media_type="application/json",
        )
    snapshot = _start_drilldown_job(
        org_id,
        project_id,
        stream=stream,
        workload=workload,
        state=raw_state,
        priority="background" if background else "interactive",
    )
    return HTMLResponse(
        content=json.dumps({
            "status": snapshot.get("status"),
            "message": snapshot.get("message"),
            "percent": snapshot.get("percent"),
        }),
        status_code=202,
        media_type="application/json",
    )


